import { afterEach, describe, expect, it, vi } from "vitest";
import fs from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { randomUUID } from "node:crypto";
import { DraftStore } from "../src/chat/draft-store.js";

// Regression coverage: "草稿写失败保留旧记录" — an atomic write that fails to
// publish must leave the previous manifest recoverable, and a failed send must
// not have cleared the composer in advance.

const roots = [];
afterEach(async () => {
  for (const root of roots.splice(0))
    await fs.rm(root, { recursive: true, force: true });
});
async function storage() {
  const root = await fs.mkdtemp(path.join(tmpdir(), "cc-draft-"));
  roots.push(root);
  return root;
}
const image = {
  data: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==",
};

describe("atomic write preserves the previous draft record", () => {
  it("keeps the old composer recoverable when a save publish fails", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "original", images: [image] });
    const before = (await fs.readdir(path.join(root, key))).sort();
    const rename = vi
      .spyOn(fs, "rename")
      .mockRejectedValueOnce(new Error("ENOSPC"));
    try {
      await expect(
        store.save(key, { text: "replacement", images: [image] }),
      ).rejects.toThrow("ENOSPC");
    } finally {
      rename.mockRestore();
    }
    // Old draft is recovered; the failed write added nothing and left no
    // temporary manifest or unreferenced image behind.
    const restored = await store.view(key);
    expect(restored.composer.text).toBe("original");
    expect(restored.composer.images[0].data).toBe(image.data);
    expect((await fs.readdir(path.join(root, key))).sort()).toEqual(before);
  });

  it("publishes the new composer when a save rename succeeds", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "original", images: [image] });
    await store.save(key, { text: "published", images: [] });
    const restored = await store.view(key);
    expect(restored.composer.text).toBe("published");
    expect(restored.composer.images).toEqual([]);
  });

  it("does not clear the composer in advance when a send publish fails", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "old draft", images: [image] });
    const before = (await fs.readdir(path.join(root, key))).sort();
    const rename = vi
      .spyOn(fs, "rename")
      .mockRejectedValueOnce(new Error("ENOSPC"));
    try {
      await expect(
        store.prepare(key, "session-1", "input-1", {
          text: "submitted",
          images: [image],
        }),
      ).rejects.toThrow("ENOSPC");
    } finally {
      rename.mockRestore();
    }
    const restored = await store.view(key);
    // Sending must not have cleared the composer: the failed prepare's publish
    // never committed, so the old draft stays the recoverable state.
    expect(restored.composer.text).toBe("old draft");
    expect(restored.composer.images[0].data).toBe(image.data);
    expect(restored.pending).toEqual([]);
    expect((await fs.readdir(path.join(root, key))).sort()).toEqual(before);
  });

  it("clears the composer only after a send publish succeeds", async () => {
    const root = await storage();
    const key = randomUUID();
    const store = new DraftStore(root);
    await store.save(key, { text: "old draft", images: [image] });
    const prepared = await store.prepare(key, "session-1", "input-1", {
      text: "submitted",
      images: [],
    });
    const restored = await store.view(key);
    expect(restored.composer.text).toBe("");
    expect(restored.composer.images).toEqual([]);
    expect(restored.pending).toEqual([
      expect.objectContaining({ id: "input-1", status: "prepared" }),
    ]);
    expect(prepared.paths).toEqual([]);
  });
});

