    h.provider._webviewReady = true;
    h.provider._handleMessage({ type: "closeTab", id: conv.id });
    expect((await h.provider._draftStore.list()).map((d) => d.label)).toContain(
      "closed draft",
    );
    h.provider.reopenClosedSession();
    expect(h.provider._activeConv().draftKey).toBe(conv.draftKey);
    expect(h.sessions).toEqual([]);
  });
});

function webview(backup, { withoutRandomUUID = false } = {}) {
  const window = new Window({
    settings: {
      enableJavaScriptEvaluation: true,
      disableCSSFileLoading: true,
      disableJavaScriptFileLoading: true,
    },
  });
  const posted = [];
  // This harness tests ACK/page routing; actual codecs run in the separate
  // Chromium journey. Keep completion explicit so ACK alone cannot show img.
  const decoders = [];
  window.HTMLCanvasElement.prototype.getContext = () => ({
    clearRect() {},
    drawImage() {},
  });
  window.Worker = class {
    constructor() {
      decoders.push(this);
    }
    postMessage(images) {
      this.images = images;
    }
    terminate() {
      this.terminated = true;
    }
  };
  if (withoutRandomUUID)
    Object.defineProperty(window, "crypto", {
      value: {
        getRandomValues: window.crypto.getRandomValues.bind(window.crypto),
      },
    });
  let state = backup || {};
  window.acquireVsCodeApi = () => ({
    postMessage: (m) => posted.push(m),
    getState: () => state,
    setState: (s) => {
      state = s;
    },
  });
  window.document.write(
    buildChatHtml({ nonce: "n", cspSource: "vscode-resource:" }),
  );
  const emit = (data) =>
    window.dispatchEvent(new window.MessageEvent("message", { data }));
  const keys = {
    a: "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa",
    b: "bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb",
  };
  const tabs = (id) =>
    emit({
      kind: "tabs",
      activeId: id,
      tabs: Object.keys(keys).map((id) => ({
        id,
        title: id,
        draftKey: keys[id],
        draftStorage: true,
      })),
    });
  return {
    window,
    posted,
    decoders,
    emit,
    keys,
    tabs,
    input: window.document.getElementById("input"),
    state: () => state,
    page: posted.find((m) => m.type === "ready"),
  };
}
describe("composer recovery in the generated Webview", () => {
  it("initializes the page and draft handshake without the secure-context randomUUID API", async () => {
    const ui = webview(undefined, { withoutRandomUUID: true });
